#include "engine.hpp"
#include <iostream>
using namespace uaa;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
int main(int argc,char** argv){try{check(argc==3,"Expected data and directory");Engine e(argv[1],argv[2]);e.createBase("AMPHIBIOUS",0,0);check(e.footprint("underwater-robot")==std::pair<int,int>{4,8},"Underwater robot has the requested 4x8 footprint");e.state["nextUfo"]=100000.;std::vector<int> soldiers;int pilot=-1,nav=-1;for(int i=0;i<int(e.state["personnel"].size());++i){auto role=e.state["personnel"][i]["role"];if(role=="pilot"&&pilot<0)pilot=i;if(role=="navigator"&&nav<0)nav=i;if(role=="soldier")soldiers.push_back(i);}check(e.aircraftCanOperate(1,"AIR")&&e.aircraftCanOperate(1,"UNDERWATER")&&!e.aircraftCanOperate(0,"UNDERWATER"),"Only amphibious transport operates underwater");check(e.setAircraftMode(1,"UNDERWATER").ok&&e.assignCrew(1,"pilot",pilot).ok&&e.assignCrew(1,"navigator",nav).ok,"Configure underwater mode and crew");check(e.toggleTransportSoldier(1,soldiers[0]).ok&&e.toggleTransportSoldier(1,soldiers[1]).ok,"Assign operation soldiers");auto before=e.state;check(!e.departTransport(1).ok&&e.state==before,"Unprepared soldiers block departure atomically without losing fuel");auto reasons=e.transportReadiness(1)["reasons"];check(reasons.size()==2&&reasons[0]["missing"].size()==3,"Each unprepared soldier and all three missing items are reported");
 e.state["stock"]["diving-suit"]=2;e.state["stock"]["rebreather"]=2;e.state["stock"]["diving-hood"]=2;for(int p:soldiers){e.state["personnel"][p]["attributes"]["STRENGTH"]=100;if(p!=soldiers[0]&&p!=soldiers[1])continue;check(e.equipSoldier(p,"divingSuit","diving-suit").ok&&e.equipSoldier(p,"rebreather","rebreather").ok&&e.equipSoldier(p,"divingHood","diving-hood").ok,"Equip real underwater gear from storage");}check(e.transportReadiness(1)["ready"]==true,"All assigned soldiers ready only after all three gear pieces are equipped");check(e.setTransportRobot(1,true,"AIR").ok&&!e.transportReadiness(1)["ready"].get<bool>(),"Optional robot requires actual warehouse chassis, weapon and ammunition");e.state["stock"]["underwater-robot"]=1;e.state["stock"]["compressed-air-cannon"]=1;e.state["stock"]["air-round"]=20;
 e.ensureLocations();e.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",0.},{"lon",0.},{"hull",100.},{"spawned",0.},{"expires",720.},{"environment","SEA"}});e.processRadarContacts(0,0);check(e.setTransportTarget(1,0).ok,"Select a real detected sea UFO");check(e.departTransport(1).ok&&e.state["craft"][1]["operationState"]=="DEPLOYED"&&e.state["stock"]["underwater-robot"]==0&&e.state["stock"]["air-round"]==0,"Departure reserves robot, weapon and magazine only after all safety checks");check(!e.equipSoldier(soldiers[0],"rebreather","").ok&&!e.setAircraftMode(1,"AIR").ok,"Cannot remove required gear or change mode during operation");e.rng.seed(1);check(e.fireUnderwaterRobot(1).ok&&e.state["ufos"][0]["hull"]==92.&&e.state["craft"][1]["robotAmmo"]["AIR"]==19,"Compressed-air shot consumes ammunition and damages actual underwater target");e.save(1);Engine loaded(argv[1],argv[2]);check(loaded.load(1).ok&&loaded.state["craft"][1]["robotAmmo"]["AIR"]==19,"Deployed squad, gear and robot ammunition survive save/load");auto corrupt=readJson(e.userDir/"save-1.json");corrupt["personnel"][soldiers[0]]["loadout"]["rebreather"]="";writeJson(e.userDir/"save-2.json",corrupt);auto saved=loaded.state;check(!loaded.load(2).ok&&loaded.state==saved,"Save tampering cannot bypass underwater departure safety");check(e.returnTransport(1).ok&&e.state["stock"]["underwater-robot"]==1&&e.state["stock"]["air-round"]==19&&!e.returnTransport(1).ok,"Return restores chassis and unused ammunition exactly once");
 e.state["stock"]["underwater-torpedo-launcher"]=1;e.state["stock"]["underwater-torpedo"]=4;check(e.setTransportRobot(1,true,"TORPEDO").ok&&e.departTransport(1).ok&&(e.rng.seed(1),e.fireUnderwaterRobot(1).ok)&&e.state["ufos"][0]["hull"]==57.,"Torpedo weapon uses its own ammunition and damage");check(e.returnTransport(1).ok&&e.state["stock"]["underwater-torpedo"]==3,"Unused torpedoes return to storage");e.state["ufos"][0]["environment"]="AIR";check(e.setTransportRobot(1,false,"AIR").ok&&e.setAircraftMode(1,"AIR").ok,"Transport retains flight capability");check(e.equipSoldier(soldiers[0],"divingSuit","").ok&&e.transportReadiness(1)["ready"]==true,"Air operation does not require underwater equipment");check(e.state["stock"].value("underwater-robot",0)==1&&e.record("units","underwater-robot")&&e.record("equipment","air-round"),"Optional robot is a tank entry with separate purchasable ammunition");check(e.record("units","light-tank")->at("vehicleStats")["health"]==150&&e.record("units","underwater-robot")->at("vehicleStats")["timeUnits"]==60,"Both tank types expose health and time-unit profiles");e.state["ufos"][0]["environment"]="SEA";e.processRadarContacts(0,e.state["hours"]);check(e.equipSoldier(soldiers[0],"divingSuit","diving-suit").ok&&e.setAircraftMode(1,"UNDERWATER").ok,"Prepare dual-weapon underwater mission");check(e.setTransportRobot(1,true,"AIR").ok&&e.toggleRobotWeapon(1,"TORPEDO").ok&&e.robotWeapons(1).size()==2,"Cannon and torpedo systems can be selected independently together");check(e.departTransport(1).ok,"Dispatch both optional weapon systems");e.rng.seed(1);check(e.fireUnderwaterRobot(1,"AIR","hip").ok&&e.state["craft"][1]["robotTU"]==40,"Hip fire consumes its own time-unit cost");e.rng.seed(1);check(e.fireUnderwaterRobot(1,"TORPEDO","aimed").ok&&e.state["craft"][1]["robotTU"]==0,"Aimed torpedo fire consumes a different time-unit cost");auto noTU=e.state;check(!e.fireUnderwaterRobot(1,"AIR","hip").ok&&e.state==noTU,"Insufficient TU cannot consume ammunition");check(e.nextRobotTurn(1).ok&&e.state["craft"][1]["robotTU"]==60&&e.returnTransport(1).ok,"New turn restores time units and return preserves independent magazines");auto locked=e.state;check(!e.toggleRobotWeapon(1,"AIR_MK2").ok&&e.state==locked&&!e.manufactureQuote("equipment","compressed-air-cannon-mk2")["ok"].get<bool>(),"Unfinished research gates both advanced loadout and manufacture");e.state["research"]["research_basic_lab"]=1.;check(e.startResearch("research_underwater_ballistics").ok,"Advanced robot weapon is a real research project");for(std::size_t i=0;i<e.state["personnel"].size();++i)if(e.state["personnel"][i]["role"]=="scientist")check(e.assignScientist("research_underwater_ballistics",i,true).ok,"Assign scientists to underwater weapon research");e.advance(96);check(e.state["research"]["research_underwater_ballistics"]==1.&&e.toggleRobotWeapon(1,"AIR_MK2").ok&&e.robotWeapons(1).size()==2,"Completed research unlocks upgraded cannon while preserving the torpedo slot");std::cout<<"PASS: amphibious modes, four-person squad, per-soldier underwater gear, atomic departure safety, robot allocation, air rounds/torpedoes, damage, returns and validated save/load\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
